window.MANIFEST = {"schema":1,"git":{"commit":"dc815e2","branch":"main","remote":"http://github.com/pythongiant/KVBoost"},"feature_groups":[{"id":"core","label":"Core engine","color":"#4f46e5","emoji":"\ud83e\udde0","matches":["engine.py","models.py","compat.py"],"tagline":"Inference engine, model loading, HF compatibility."},{"id":"cache","label":"Chunk reuse","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","matches":["chunk_registry.py","cache_manager.py","prompt_assembler.py","selective_recompute.py","cacheblend.py","kv_quantize.py","disk_tier.py","batch.py"],"tagline":"Content-hashed KV chunks, prefix assembly, selective recompute."},{"id":"flash","label":"Flash attention","color":"#f97316","emoji":"\u26a1","matches":["flash_attn_ext.py","csrc"],"tagline":"Custom FlashAttention-2 CUDA kernel + Python wrapper."},{"id":"streaming","label":"AWQ Layer Streaming","color":"#a855f7","emoji":"\ud83c\udf0a","matches":["streaming"],"tagline":"Stream AWQ layer weights from host RAM to run models bigger than VRAM."},{"id":"paged","label":"CPU paged decode","color":"#10b981","emoji":"\ud83d\udcd1","matches":["cpu_paged"],"tagline":"Block-paged KV cache for CPU-bound serving."},{"id":"server","label":"OpenAI-compatible server","color":"#ec4899","emoji":"\ud83d\ude80","matches":["server"],"tagline":"FastAPI server with batching, streaming, tool calls."}],"modules":[{"name":"kvboost","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/__init__.py","rel_path":"src/kvboost/__init__.py","summary":"KVBoost \u2014 Chunk-level KV cache reuse for faster HuggingFace inference.","docstring":"KVBoost \u2014 Chunk-level KV cache reuse for faster HuggingFace inference.\n\nUsage:\n    from kvboost import KVBoost\n\n    engine = KVBoost.from_pretrained(\"Qwen/Qwen2.5-3B\")\n    engine.warm(\"You are a helpful assistant. ...\")\n    result = engine.generate(\"You are a helpful assistant. ...\n\nUser: Hello\")\n    print(result.output_text)\n\nRecompute strategies:\n    from kvboost import KVBoost, RecomputeStrategy\n\n    # Original: fix last R tokens at each chunk seam\n    engine = KVBoost.from_pretrained(\"...\", recompute_strategy=\"selective\")\n\n    # CacheBlend: fix only the ~15% most deviated tokens (smarter, faster)\n    engine = KVBoost.from_pretrained(\"...\", recompute_strategy=\"cacheblend\")\n\n    # None: skip recompute entirely (fastest, slight quality risk)\n    engine = KVBoost.from_pretrained(\"...\", recompute_strategy=\"none\")","loc":74,"bytes":2798,"group":"core","color":"#4f46e5","emoji":"\ud83e\udde0","classes":[],"functions":[]},{"name":"kvboost.batch","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/batch.py","rel_path":"src/kvboost/batch.py","summary":"Batch Inference =============== Processes multiple prompts sharing a common prefix in a single batched forward pass.","docstring":"Batch Inference\n===============\nProcesses multiple prompts sharing a common prefix in a single batched\nforward pass. The shared prefix KV is loaded from cache once, then\nbroadcast (zero-copy via expand()) across the batch for the suffix prefill.\n\nKey operations:\n  - find_common_chunk_prefix: detect shared prefix across prompts\n  - broadcast_kv: expand [1, H, S, D] \u2192 [B, H, S, D] without copying\n  - group_by_prefix: auto-cluster prompts by shared prefix hash\n  - batched_decode: decode loop for multiple sequences in parallel","loc":151,"bytes":5609,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[],"functions":[{"name":"find_common_chunk_prefix","kind":"function","lineno":31,"summary":"Returns length of the longest chunk-aligned prefix shared by all prompts.","is_public":true},{"name":"broadcast_kv","kind":"function","lineno":57,"summary":"Expand cached KV from [1, heads, seq, dim] to [batch, heads, seq, dim].","is_public":true},{"name":"pad_and_mask","kind":"function","lineno":69,"summary":"Pad suffix token lists to equal length.","is_public":true},{"name":"group_by_prefix","kind":"function","lineno":86,"summary":"Group prompt indices by the hash of their first N chunks.","is_public":true},{"name":"batched_decode","kind":"function","lineno":107,"summary":"Batched autoregressive decode loop.","is_public":true}]},{"name":"kvboost.cache_manager","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cache_manager.py","rel_path":"src/kvboost/cache_manager.py","summary":"KVCacheManager ============== Two-tier storage with two-tier keying:","docstring":"KVCacheManager\n==============\nTwo-tier storage with two-tier keying:\n\n  Storage tiers:\n    Tier 1 (hot)  : in-process dict, tensors on CPU RAM\n    Tier 2 (cold) : mmap'd files on disk via torch.save / torch.load\n\n  Key tiers:\n    prefix_hash   : hash(parent_hash, tokens) \u2014 exact match, positionally correct\n    content_hash  : hash(tokens) \u2014 approximate match, needs full recompute\n\n  Lookup order:\n    1. Try prefix_hash (exact) \u2192 use directly\n    2. Try content_hash (approximate) \u2192 use but flag for full recompute\n\nEviction policy: hard byte budget with recency window + importance-based eviction.\n\n  - max_cache_bytes is required and enforced on every store().\n  - The most-recently-stored `recency_window_chunks` are pinned (never evicted).\n  - Chunks whose content_hash appears in `pinned_content_hashes` are also pinned\n    unconditionally, regardless of recency. Use pin_content() for system prompts\n    or other chunks that must survive across long conversations.\n  - When budget is exceeded, chunks outside both pin sets are evicted lowest\n    importance first (ties \u2192 LRU). Pruned = evicted: a dropped chunk is\n    gone entirely and becomes a cache miss on next lookup (recomputed on demand).","loc":501,"bytes":22951,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"ChunkMatch","kind":"class","lineno":46,"summary":"Result of a cache lookup \u2014 tracks whether the match is exact or approximate.","is_public":true},{"name":"KVCacheManager","kind":"class","lineno":55,"summary":"","is_public":true}],"functions":[]},{"name":"kvboost.cacheblend","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cacheblend.py","rel_path":"src/kvboost/cacheblend.py","summary":"CacheBlend Recompute ==================== An alternative to SelectiveRecompute that fixes stale KV tensors *statistically* rather than *spatially*.","docstring":"CacheBlend Recompute\n====================\nAn alternative to SelectiveRecompute that fixes stale KV tensors\n*statistically* rather than *spatially*.\n\nProblem (same as SelectiveRecompute)\n------------------------------------\nWhen independently-cached chunks are stitched together, their KV tensors\nare \"stale\" \u2014 each chunk was encoded without cross-chunk attention context.\n\nWhy SelectiveRecompute is suboptimal\n------------------------------------\nSelectiveRecompute blindly recomputes the last R tokens at every chunk seam.\nThis is both too broad (recomputes tokens that may not actually deviate) and\ntoo narrow (misses tokens inside a chunk that depend on cross-chunk context).\nIn practice it costs ~79% of full prefill (Experiment 2: 553ms vs 703ms).\n\nCacheBlend approach\n-------------------\n1. Concatenate all cached KV chunks into one assembled tensor\n2. Run a single forward pass over the cached token IDs with the assembled\n   KV as context \u2014 this produces \"what KV *would* be with full attention\"\n3. Compare the updated KV against the cached KV per token per layer using\n   cosine distance \u2014 tokens that deviate significantly are the ones that\n   actually need fixing\n4. Recompute only the top-k% most deviated tokens (default 15%)\n\nThe result: ~15% of tokens recomputed instead of O(R * num_seams), and\nthe tokens chosen are the ones that actually matter for output quality.\n\nReference: CacheBlend (USENIX ATC '25)\n\nTrade-off knobs\n---------------\nrecompute_ratio : fraction of tokens to recompute (default 0.15 = 15%)\n                  Higher \u2192 better quality, more compute.\n                  Lower  \u2192 faster, slight quality risk.\nmin_deviation   : minimum cosine distance to consider a token \"deviated\".\n                  Tokens below this are never recomputed regardless of ratio.","loc":183,"bytes":8742,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"CacheBlendRecompute","kind":"class","lineno":58,"summary":"","is_public":true}],"functions":[]},{"name":"kvboost.chunk_registry","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/chunk_registry.py","rel_path":"src/kvboost/chunk_registry.py","summary":"ChunkRegistry ============= Splits text into cacheable chunks and owns the chunk_size policy.","docstring":"ChunkRegistry\n=============\nSplits text into cacheable chunks and owns the chunk_size policy.\n\nChunking strategies\n-------------------\nFIXED      : fixed token-count windows (default, predictable)\nSEMANTIC   : split on paragraph / sentence boundaries (better reuse)\nDOCUMENT   : treat entire document as one chunk","loc":175,"bytes":7127,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"ChunkStrategy","kind":"class","lineno":25,"summary":"","is_public":true},{"name":"ChunkRegistry","kind":"class","lineno":31,"summary":"Converts (text, token_ids) into a list of (start, end, sub_token_ids) triples according to the configured strategy.","is_public":true}],"functions":[]},{"name":"kvboost.compat","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/compat.py","rel_path":"src/kvboost/compat.py","summary":"Model Compatibility =================== KVBoost's position-ID stitching assumes RoPE positional encoding where positions are passed explicitly via position_ids and the model correc","docstring":"Model Compatibility\n===================\nKVBoost's position-ID stitching assumes RoPE positional encoding where\npositions are passed explicitly via position_ids and the model correctly\nhandles non-contiguous sequences.\n\nThis module tracks which HuggingFace architectures are known-safe, which\nare known-broken, and provides runtime validation for untested models.\n\nKnown-broken architectures:\n  - ALiBi models (MPT, Falcon): positional bias added directly to attention\n    scores based on distance \u2014 no position_ids injection possible\n  - Learned absolute embeddings (GPT-2): position info baked into token\n    representations at the input layer, irreversible by KV stitching\n  - Sliding window attention (Mistral with sliding_window != None): KV from\n    outside the window includes tokens that should have been masked","loc":186,"bytes":7994,"group":"core","color":"#4f46e5","emoji":"\ud83e\udde0","classes":[{"name":"_LastTokenHead","kind":"class","lineno":67,"summary":"Wraps an LM head so it projects only the final sequence position on the forward pass.","is_public":false},{"name":"last_logit_only","kind":"class","lineno":86,"summary":"Context manager that temporarily replaces the model's LM head with a last-position-only projection.","is_public":true}],"functions":[{"name":"logits_to_keep_kwargs","kind":"function","lineno":35,"summary":"Return {\"logits_to_keep\": 1} (or {\"num_logits_to_keep\": 1}) if the given model's forward accepts either, else {}.","is_public":true},{"name":"default_device","kind":"function","lineno":121,"summary":"Return the best available device: cuda > mps > cpu.","is_public":true},{"name":"check_model_compatibility","kind":"function","lineno":172,"summary":"Validate that a model's architecture is compatible with KV cache stitching.","is_public":true}]},{"name":"kvboost.cpu_paged","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cpu_paged/__init__.py","rel_path":"src/kvboost/cpu_paged/__init__.py","summary":"from .block_allocator import BlockAllocator from .paged_attn_cpu import paged_attention_fwd from .chunk_to_blocks import ChunkBlockMapper from .cpu_engine import CPUPagedEngine","docstring":"","loc":10,"bytes":287,"group":"paged","color":"#10b981","emoji":"\ud83d\udcd1","classes":[],"functions":[]},{"name":"kvboost.cpu_paged.block_allocator","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cpu_paged/block_allocator.py","rel_path":"src/kvboost/cpu_paged/block_allocator.py","summary":"Physical block allocator for CPU paged attention.","docstring":"Physical block allocator for CPU paged attention.\n\nLayout\n------\nThe entire KV pool for *one layer* lives in a single pre-allocated tensor:\n\n    kv_pool : [num_blocks, 2, num_heads, block_size, head_dim]\n               ^           ^  ^          ^            ^\n               block_id   K/V heads     tokens/block  features\n\nA sequence's KV is described by a block_table (list of physical block_ids).\nLogical token i lives in:\n    block_id  = block_table[i // block_size]\n    slot      = i % block_size\n\nAll layers share the same block_table for a sequence; each layer has its own\npool tensor of identical shape.\n\nCopy-on-write prefix sharing\n-----------------------------\nWhen two sequences share a KVBoost prefix chunk (same prefix_hash) they point\nto the same physical blocks for that prefix.  Before any write to a block we\ncheck ref_count; if > 1 we copy the block to a fresh allocation first.\n\nImplementation\n--------------\nBookkeeping (free list, ref counts, copy-on-write decisions) runs in Rust via\nthe optional ``kvboost_native`` extension. If that extension is not installed,\nfalls back transparently to a pure-Python implementation. Tensor pools and\nthe actual KV reads/writes always stay on the Python side.","loc":242,"bytes":10146,"group":"paged","color":"#10b981","emoji":"\ud83d\udcd1","classes":[{"name":"_PyMeta","kind":"class","lineno":49,"summary":"Pure-Python fallback that mirrors the Rust BlockAllocatorMeta API.","is_public":false},{"name":"_PyCowDecision","kind":"class","lineno":116,"summary":"","is_public":false},{"name":"BlockAllocator","kind":"class","lineno":130,"summary":"Manages a fixed pool of physical KV blocks across all layers.","is_public":true}],"functions":[{"name":"_make_meta","kind":"function","lineno":124,"summary":"","is_public":false}]},{"name":"kvboost.cpu_paged.chunk_to_blocks","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cpu_paged/chunk_to_blocks.py","rel_path":"src/kvboost/cpu_paged/chunk_to_blocks.py","summary":"Bridge between KVBoost CachedChunks and the BlockAllocator physical block pool.","docstring":"Bridge between KVBoost CachedChunks and the BlockAllocator physical block pool.\n\nWhen KVBoost's cache_manager returns a CachedChunk its past_key_values are\nstored as standard HuggingFace tensors:\n\n    past_key_values[layer] = (K, V)\n    K, V shape: [1, num_heads, chunk_len, head_dim]\n\nChunkBlockMapper writes these tensors into the physical block pool and maintains\na mapping chunk_id \u2192 block_ids so blocks can be freed when a chunk is evicted.\n\nPrefix sharing\n--------------\nIf two assembled prompts share a chunk (same prefix_hash), their block_tables\npoint to the same physical blocks via BlockAllocator.fork().  Any write during\nthe decode phase triggers copy-on-write via BlockAllocator.ensure_writable().\n\nIntegration with KVCacheManager\n--------------------------------\nRegister `mapper.on_evict` as an eviction callback on KVCacheManager so blocks\nare freed whenever a chunk leaves the hot tier.  This keeps the block pool and\nthe KV cache in sync without a GC pass.","loc":115,"bytes":5891,"group":"paged","color":"#10b981","emoji":"\ud83d\udcd1","classes":[{"name":"ChunkBlockMapper","kind":"class","lineno":40,"summary":"Manages the lifecycle of physical blocks corresponding to CachedChunks.","is_public":true}],"functions":[]},{"name":"kvboost.cpu_paged.cpu_engine","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cpu_paged/cpu_engine.py","rel_path":"src/kvboost/cpu_paged/cpu_engine.py","summary":"CPUPagedEngine ============== Subclass of InferenceEngine that replaces the decode loop with a paged attention implementation backed by BlockAllocator.","docstring":"CPUPagedEngine\n==============\nSubclass of InferenceEngine that replaces the decode loop with a paged\nattention implementation backed by BlockAllocator.\n\nKey differences from InferenceEngine\n-------------------------------------\n1. During _decode_with_kv():\n   - Cached KV tensors (assembled.cached_past_kv) are loaded into the block\n     pool via ChunkBlockMapper rather than passed as past_key_values.\n   - The prefill forward and each decode step use paged_attention_fwd() to\n     read K/V from the block pool.\n   - New K/V computed during prefill/decode are appended back into the pool\n     via append_kv_to_blocks().\n\n2. The HuggingFace model's attention layers are monkey-patched to redirect\n   their K/V reads/writes through the block pool during paged_attn phases.\n\n3. Everything else (warm(), chunk hashing, recompute strategies, quantization,\n   eviction) is fully inherited from InferenceEngine.\n\nUsage\n-----\n    from kvboost.cpu_paged import CPUPagedEngine\n\n    engine = CPUPagedEngine.from_pretrained(\n        \"Qwen/Qwen2.5-3B\",\n        max_cache_bytes=4_000_000_000,\n        block_size=16,\n        num_blocks=8192,\n    )\n    engine.warm(\"System prompt ...\")\n    result = engine.generate(\"System prompt ...\n\nUser question\", max_new_tokens=256)","loc":451,"bytes":21833,"group":"core","color":"#4f46e5","emoji":"\ud83e\udde0","classes":[{"name":"CPUPagedEngine","kind":"class","lineno":72,"summary":"InferenceEngine with a CPU paged attention decode loop.","is_public":true}],"functions":[{"name":"_infer_model_dims","kind":"function","lineno":58,"summary":"Infer (num_layers, num_kv_heads, head_dim) from the model config.","is_public":false}]},{"name":"kvboost.cpu_paged.paged_attn_cpu","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/cpu_paged/paged_attn_cpu.py","rel_path":"src/kvboost/cpu_paged/paged_attn_cpu.py","summary":"CPU paged attention forward pass.","docstring":"CPU paged attention forward pass.\n\nImplements attention where K and V are stored in a block pool managed by\nBlockAllocator rather than in contiguous tensors.  Optimised for CPU via\nindex_select + batched matmul \u2014 no custom C extension required.\n\nTwo modes\n---------\nPrefill (query_len > 1):\n    Computes full self-attention over [query_len, kv_len] using gathered K/V.\n    Used when processing uncached or live tokens.\n\nDecode (query_len == 1):\n    Computes attention for a single new token over the full KV history.\n    This is the tight inner loop during autoregressive generation.\n\nAll shapes follow HuggingFace convention:\n    Q, K, V, O : [batch, num_heads, seq, head_dim]","loc":132,"bytes":4989,"group":"paged","color":"#10b981","emoji":"\ud83d\udcd1","classes":[],"functions":[{"name":"paged_attention_fwd","kind":"function","lineno":33,"summary":"Paged attention forward for one transformer layer.","is_public":true},{"name":"append_kv_to_blocks","kind":"function","lineno":111,"summary":"Append K/V for one or more new tokens into the block pool.","is_public":true}]},{"name":"kvboost.disk_tier","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/disk_tier.py","rel_path":"src/kvboost/disk_tier.py","summary":"Disk Tier \u2014 Memory-Mapped KV Cache Storage =========================================== Replaces per-file torch.save/load with a single pre-allocated memory-mapped file for zero-cop","docstring":"Disk Tier \u2014 Memory-Mapped KV Cache Storage\n===========================================\nReplaces per-file torch.save/load with a single pre-allocated\nmemory-mapped file for zero-copy, async-friendly disk caching.\n\nDesign:\n  cache_dir/\n    kv_cache.bin   \u2190 one file, flat block pool of raw tensors\n    kv_index.json  \u2190 hash \u2192 (slot, metadata) mapping\n\nEach \"slot\" holds the flattened raw bytes for one chunk's KV tensors.\nReads are zero-copy page faults via torch.from_file(). Writes are\ndirect memory copies into the mapped region. No pickle, no per-file\nsyscall overhead.\n\nFor CUDA devices, reads can be issued with non_blocking=True to\npipeline disk\u2192GPU transfer with other work.","loc":233,"bytes":9521,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"DiskTier","kind":"class","lineno":36,"summary":"Memory-mapped disk cache for KV tensors.","is_public":true}],"functions":[]},{"name":"kvboost.engine","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/engine.py","rel_path":"src/kvboost/engine.py","summary":"InferenceEngine (exported as KVBoost) ===================================== Ties together: model / tokenizer KVCacheManager ChunkRegistry PromptAssembler SelectiveRecompute","docstring":"InferenceEngine (exported as KVBoost)\n=====================================\nTies together:\n  model / tokenizer\n  KVCacheManager\n  ChunkRegistry\n  PromptAssembler\n  SelectiveRecompute\n\nExposes three generation modes for benchmarking:\n  BASELINE        \u2014 standard HF generate, no caching\n  PREFIX_CACHE    \u2014 exact prefix caching only (control)\n  CHUNK_KV_REUSE  \u2014 full chunk-level KV reuse + selective recompute\n\nUsage\n-----\n    from kvboost import KVBoost\n\n    engine = KVBoost.from_pretrained(\"Qwen/Qwen2.5-3B\")\n    engine.warm(\"You are a helpful assistant.\")\n    result = engine.generate(\"You are a helpful assistant.\n\nHello!\")\n    print(result.output_text)","loc":973,"bytes":44404,"group":"core","color":"#4f46e5","emoji":"\ud83e\udde0","classes":[{"name":"GenerationMode","kind":"class","lineno":49,"summary":"","is_public":true},{"name":"RecomputeStrategy","kind":"class","lineno":55,"summary":"","is_public":true},{"name":"GenerationResult","kind":"class","lineno":62,"summary":"","is_public":true},{"name":"InferenceEngine","kind":"class","lineno":76,"summary":"","is_public":true}],"functions":[]},{"name":"kvboost.flash_attn_ext","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/flash_attn_ext.py","rel_path":"src/kvboost/flash_attn_ext.py","summary":"Flash Attention integration for KVBoost.","docstring":"Flash Attention integration for KVBoost.\n\nThree-tier attention fallback:\n  1. kvboost._flash_attn_cuda  \u2014 custom CUDA kernel (this repo, Ampere+)\n  2. torch SDPA flash          \u2014 cuDNN FlashAttention via enable_flash_sdp(True)\n  3. vanilla SDPA              \u2014 default PyTorch, O(N\u00b2) memory\n\ninstall_flash_attention(model) replaces the scaled_dot_product_attention call\ninside every supported transformer attention module with the best available\nimplementation.  The rest of the forward pass (RoPE, projections, output,\npast_key_values) is completely unchanged, so KVBoost's position_ids injection\nand KV extraction continue to work transparently.\n\nUsage (called automatically by InferenceEngine.__init__):\n    from kvboost.flash_attn_ext import install_flash_attention\n    install_flash_attention(model)","loc":411,"bytes":18594,"group":"flash","color":"#f97316","emoji":"\u26a1","classes":[],"functions":[{"name":"flash_attention_available","kind":"function","lineno":56,"summary":"Return True if any accelerated flash attention tier is active.","is_public":true},{"name":"get_tier","kind":"function","lineno":61,"summary":"Return the active attention tier name.","is_public":true},{"name":"_kvboost_flash_attn","kind":"function","lineno":68,"summary":"Unified attention dispatch.","is_public":false},{"name":"_make_patched_sdpa","kind":"function","lineno":119,"summary":"Return a replacement for F.scaled_dot_product_attention that routes through _kvboost_flash_attn.","is_public":false},{"name":"_resolve_forward_globals","kind":"function","lineno":141,"summary":"Find the global namespace where the module's forward function looks up `scaled_dot_product_attention`.","is_public":false},{"name":"_patch_module","kind":"function","lineno":170,"summary":"Monkey-patch a single attention module to use _kvboost_flash_attn.","is_public":false},{"name":"install_flash_attention","kind":"function","lineno":215,"summary":"Walk all sub-modules of *model* and patch attention modules to use the best available flash attention implementation.","is_public":true},{"name":"uninstall_flash_attention","kind":"function","lineno":239,"summary":"Restore all patched attention modules to their original forward methods.","is_public":true},{"name":"_get_attn_registry","kind":"function","lineno":281,"summary":"Return the ALL_ATTENTION_FUNCTIONS registry dict if the model uses one (transformers 5.x), otherwise None.","is_public":false},{"name":"_make_paged_attn_fn","kind":"function","lineno":295,"summary":"Return a replacement for the model's attention dispatch function.","is_public":false},{"name":"install_paged_attention","kind":"function","lineno":403,"summary":"Monkey-patch every attention module in *model* so that its attention call reads K/V from the BlockAllocator pool rather than from past_key_values.","is_public":true},{"name":"uninstall_paged_attention","kind":"function","lineno":481,"summary":"Remove paged attention patches, restoring original forwards.","is_public":true}]},{"name":"kvboost.kv_quantize","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/kv_quantize.py","rel_path":"src/kvboost/kv_quantize.py","summary":"KV Cache Quantization ===================== Compress cached KV tensors from float16 to int8 or int4 using the asymmetric scheme from KIVI (ICML 2024):","docstring":"KV Cache Quantization\n=====================\nCompress cached KV tensors from float16 to int8 or int4 using the\nasymmetric scheme from KIVI (ICML 2024):\n\n  - Key cache: quantized **per-channel** (outliers are channel-specific)\n  - Value cache: quantized **per-token** (outliers are token-specific)\n\nThis asymmetry is critical \u2014 uniform quantization to both K and V causes\nmeasurable accuracy degradation even at int8.\n\nMemory savings:\n  int8  \u2192 2x reduction (9.4 MB \u2192 4.7 MB per chunk for Qwen2.5-3B)\n  int4  \u2192 4x reduction (9.4 MB \u2192 2.4 MB per chunk)\n  float16 \u2192 no compression (baseline)\n\nUsage:\n    from kvboost.kv_quantize import QuantizedKV, quantize_kv, dequantize_kv\n\n    # Compress for storage\n    qkv = quantize_kv(past_key_values, bits=8)\n\n    # Decompress for inference\n    past_key_values = dequantize_kv(qkv)\n\nReference: \"KIVI: A Tuning-Free Asymmetric 2bit Quantization for KV Cache\"\n           (Liu et al., ICML 2024)","loc":178,"bytes":7871,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"QuantizedLayer","kind":"class","lineno":45,"summary":"One layer's quantized K and V tensors + scale factors.","is_public":true},{"name":"QuantizedKV","kind":"class","lineno":55,"summary":"Full model's quantized KV cache \u2014 drop-in replacement for PastKVType in storage.","is_public":true}],"functions":[{"name":"_quantize_int8","kind":"function","lineno":73,"summary":"KIVI-style int8 quantization: Key: per-channel (head_dim axis) \u2014 handles channel-specific outliers Value: per-token (seq_len axis) \u2014 handles token-specific outliers","is_public":false},{"name":"_dequantize_int8","kind":"function","lineno":102,"summary":"Reconstruct KV tensors from int8 quantized storage in their original dtype.","is_public":false},{"name":"_quantize_int4","kind":"function","lineno":115,"summary":"KIVI-style int4 quantization.","is_public":false},{"name":"_dequantize_int4","kind":"function","lineno":146,"summary":"Reconstruct KV tensors from packed int4 storage in their original dtype.","is_public":false},{"name":"_pack_int4","kind":"function","lineno":159,"summary":"Pack pairs of int4 values along the last dimension into int8.","is_public":false},{"name":"_unpack_int4","kind":"function","lineno":174,"summary":"Unpack int8 back to pairs of int4 values along the last dimension.","is_public":false},{"name":"quantize_kv","kind":"function","lineno":196,"summary":"Quantize a PastKVType using KIVI-style asymmetric quantization.","is_public":true},{"name":"dequantize_kv","kind":"function","lineno":215,"summary":"Dequantize a QuantizedKV back to float16 PastKVType.","is_public":true}]},{"name":"kvboost.models","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/models.py","rel_path":"src/kvboost/models.py","summary":"Core data structures for chunk-level KV cache reuse.","docstring":"Core data structures for chunk-level KV cache reuse.\nKV tensors live in HuggingFace past_key_values format:\n  tuple[num_layers] of (key, value)\n  key/value shape: [batch=1, num_heads, seq_len, head_dim]\n\nCache Key Design\n----------------\nTwo-tier keying (inspired by vLLM v1 block hashes):\n\n  prefix_hash  : hash(parent_hash, token_ids) \u2014 unique to the full prefix\n                 chain. Same tokens at different positions or with different\n                 preceding context get different keys. Used for exact match.\n\n  content_hash : hash(token_ids) \u2014 content-only, position-independent.\n                 Used for approximate reuse: same tokens in a different\n                 context can still be a cache hit, but the chunk is flagged\n                 for mandatory full recompute (not just boundary repair).\n\nThis resolves the RoPE position collision bug (same tokens at different\npositions reusing KV encoded at wrong positions) and the cross-chunk\nattention contamination bug (KV vectors encoding the wrong preceding context).","loc":125,"bytes":6184,"group":"core","color":"#4f46e5","emoji":"\ud83e\udde0","classes":[{"name":"CachedChunk","kind":"class","lineno":36,"summary":"A single cached chunk: a slice of tokenized text + its KV tensors.","is_public":true},{"name":"AssembledPrompt","kind":"class","lineno":85,"summary":"Result of stitching cached chunks + live (uncached) tail tokens.","is_public":true},{"name":"WarmResult","kind":"class","lineno":115,"summary":"Diagnostic returned by engine.warm() to help catch alignment issues.","is_public":true}],"functions":[{"name":"content_hash_from_tokens","kind":"function","lineno":131,"summary":"Content-only hash.","is_public":true},{"name":"chained_hash","kind":"function","lineno":137,"summary":"Prefix-chained hash (vLLM-style).","is_public":true}]},{"name":"kvboost.prompt_assembler","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/prompt_assembler.py","rel_path":"src/kvboost/prompt_assembler.py","summary":"PromptAssembler =============== Given a full prompt (token_ids) and the KVCacheManager, assembles:","docstring":"PromptAssembler\n===============\nGiven a full prompt (token_ids) and the KVCacheManager, assembles:\n\n  cached_past_kv    \u2014 merged KV tensors for the reused prefix/chunks\n  live_token_ids    \u2014 tokens still needing a forward pass\n  live_position_ids \u2014 absolute positions for each live token\n  chunk_boundaries  \u2014 seam positions for SelectiveRecompute\n  has_approximate   \u2014 True if any chunk was an approximate (content-only) match\n\nTwo assembly modes\n------------------\nPREFIX_ONLY  : only the leading contiguous cached prefix is reused\n               (safe, correct, no seam issues)\nCHUNK_REUSE  : any matching chunk, anywhere in the prompt, is reused\n               (faster, seams exist \u2192 feed to recompute strategy)","loc":163,"bytes":6686,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"AssemblyMode","kind":"class","lineno":35,"summary":"","is_public":true},{"name":"PromptAssembler","kind":"class","lineno":40,"summary":"","is_public":true}],"functions":[]},{"name":"kvboost.selective_recompute","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/selective_recompute.py","rel_path":"src/kvboost/selective_recompute.py","summary":"SelectiveRecompute ================== Problem ------- When we concatenate KV caches from independently-cached chunks, each chunk's stored KV was computed with attention only over i","docstring":"SelectiveRecompute\n==================\nProblem\n-------\nWhen we concatenate KV caches from independently-cached chunks,\neach chunk's stored KV was computed with attention only over its own\ntokens (and whatever prefix preceded it at cache-time). After stitching\nchunks together the seam positions have \"stale\" KV \u2014 they didn't attend\nto cross-chunk context.\n\nThis matters primarily for the *keys and values* of the boundary tokens\n(not the queries, which are recomputed fresh for every generation step).\n\nFix\n---\nFor the last R tokens of each chunk boundary (except the final chunk),\nre-run a forward pass using the full merged KV as prefix context and\nreplace those R positions in the stitched KV with freshly computed ones.\n\nThis is \"selective\" because we only recompute O(R * num_boundaries)\ntokens rather than the full prompt.\n\nTrade-off knobs\n---------------\nrecompute_overlap   : R \u2014 how many tokens back from each seam to fix.\n                      Larger \u2192 better quality, more compute.\n                      Default 16 is a good balance for chunk_size >= 64.\nskip_if_no_seams    : skip the module entirely for pure prefix hits\n                      (no stitching was done).","loc":153,"bytes":6570,"group":"cache","color":"#0ea5e9","emoji":"\ud83d\uddc2\ufe0f","classes":[{"name":"SelectiveRecompute","kind":"class","lineno":47,"summary":"","is_public":true}],"functions":[]},{"name":"kvboost.server","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/__init__.py","rel_path":"src/kvboost/server/__init__.py","summary":"from .app import build_app from .schema import ( CompletionRequest, CompletionResponse, ChatCompletionRequest, ChatCompletionResponse, ) from .batch_queue import BatchQueue from .e","docstring":"","loc":18,"bytes":409,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[],"functions":[]},{"name":"kvboost.server.__main__","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/__main__.py","rel_path":"src/kvboost/server/__main__.py","summary":"KVBoost inference server CLI.","docstring":"KVBoost inference server CLI.\n\nUsage\n-----\n    # Minimum\n    python -m kvboost.server --model Qwen/Qwen2.5-3B\n\n    # Full options\n    python -m kvboost.server         --model Qwen/Qwen2.5-3B         --host 0.0.0.0         --port 8000         --max-cache-bytes 2e9         --chunk-size 128         --recompute-strategy cacheblend         --kv-cache-bits 8         --batch-window-ms 20         --max-batch-size 8         --max-queue-size 256         --warm \"You are a helpful assistant.\"         --device cuda         --dtype float16         --workers 1\n\n    # CPU paged attention backend\n    python -m kvboost.server         --model Qwen/Qwen2.5-3B         --backend cpu-paged         --block-size 16         --num-blocks 4096\n\nOpenAI client example\n---------------------\n    from openai import OpenAI\n    client = OpenAI(base_url=\"http://localhost:8000/v1\", api_key=\"kvboost\")\n    resp = client.chat.completions.create(\n        model=\"Qwen/Qwen2.5-3B\",\n        messages=[{\"role\": \"user\", \"content\": \"Hello!\"}],\n        max_tokens=128,\n    )\n    print(resp.choices[0].message.content)","loc":312,"bytes":14798,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[],"functions":[{"name":"parse_args","kind":"function","lineno":59,"summary":"","is_public":true},{"name":"load_engine","kind":"function","lineno":160,"summary":"","is_public":true},{"name":"main","kind":"function","lineno":291,"summary":"","is_public":true}]},{"name":"kvboost.server.app","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/app.py","rel_path":"src/kvboost/server/app.py","summary":"FastAPI application \u2014 OpenAI-compatible inference server for KVBoost.","docstring":"FastAPI application \u2014 OpenAI-compatible inference server for KVBoost.\n\nEndpoints\n---------\nGET  /health                    \u2014 liveness probe\nGET  /v1/models                 \u2014 list loaded model\nPOST /v1/completions            \u2014 text completion (streaming + non-streaming)\nPOST /v1/chat/completions       \u2014 chat completion (streaming + non-streaming)\nGET  /v1/stats                  \u2014 server / cache / queue diagnostics\nPOST /v1/warm                   \u2014 pre-warm the KV cache with a text string\n\nStreaming\n---------\nWhen stream=True the response is a text/event-stream (SSE) where each\nchunk is a JSON-encoded CompletionChunk / ChatCompletionChunk followed by\na final \"data: [DONE]\" sentinel \u2014 identical to the OpenAI streaming format.\n\nError handling\n--------------\nHTTP 400  \u2014 invalid request (Pydantic validation failure)\nHTTP 503  \u2014 request queue full (back-pressure)\nHTTP 504  \u2014 request timed out waiting for the worker\nHTTP 500  \u2014 unexpected model error","loc":529,"bytes":22835,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[],"functions":[{"name":"_truncate","kind":"function","lineno":61,"summary":"","is_public":false},{"name":"build_app","kind":"function","lineno":69,"summary":"Construct and return the FastAPI application.","is_public":true},{"name":"_filter_tool_choice","kind":"function","lineno":324,"summary":"Apply OpenAI tool_choice semantics to a parsed list of ToolCall objects.","is_public":false},{"name":"_validate_model","kind":"function","lineno":348,"summary":"","is_public":false},{"name":"_run_single","kind":"function","lineno":356,"summary":"","is_public":false},{"name":"_run_completions","kind":"function","lineno":378,"summary":"","is_public":false},{"name":"_stream_completions","kind":"function","lineno":386,"summary":"SSE generator for /v1/completions with stream=True.","is_public":false},{"name":"_stream_chat","kind":"function","lineno":435,"summary":"SSE generator for /v1/chat/completions with stream=True.","is_public":false}]},{"name":"kvboost.server.batch_queue","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/batch_queue.py","rel_path":"src/kvboost/server/batch_queue.py","summary":"Async prefix-grouped batch queue.","docstring":"Async prefix-grouped batch queue.\n\nDesign\n------\nIncoming requests are held in an asyncio.Queue.  A background coroutine\n(the collector) drains the queue every `batch_window_ms` milliseconds,\ngroups requests by their shared prefix hash (using KVBoost's\ngroup_by_prefix), and submits each group as a batch to the EngineWorker\nrunning in a thread pool.\n\nPrefix grouping strategy\n-------------------------\n1. Tokenize every request as it arrives and compute the hash of its first\n   N chunk-aligned prefix chunks (same logic as engine.group_by_prefix).\n2. At the end of the collection window, requests with the same prefix hash\n   are batched together so the engine can broadcast the shared KV once and\n   run a single batched prefill.\n3. Requests that don't share a prefix with anyone form singleton batches.\n\nBack-pressure\n-------------\nIf `max_queue_size` requests are pending, new requests are rejected with\nHTTP 503.  The caller should retry.\n\nTimeouts\n---------\nEach request has a `timeout_s` deadline.  If the worker hasn't returned\nby then the future is cancelled and the client receives HTTP 504.","loc":205,"bytes":8845,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[{"name":"QueuedRequest","kind":"class","lineno":44,"summary":"","is_public":true},{"name":"Batch","kind":"class","lineno":59,"summary":"A group of requests that share a common prefix, ready to dispatch.","is_public":true},{"name":"BatchQueue","kind":"class","lineno":73,"summary":"Asyncio-based request queue with prefix grouping.","is_public":true}],"functions":[]},{"name":"kvboost.server.engine_worker","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/engine_worker.py","rel_path":"src/kvboost/server/engine_worker.py","summary":"EngineWorker ============ Runs the KVBoost InferenceEngine in a dedicated background thread and exposes an async interface so FastAPI handlers can await results without blocking th","docstring":"EngineWorker\n============\nRuns the KVBoost InferenceEngine in a dedicated background thread and\nexposes an async interface so FastAPI handlers can await results without\nblocking the event loop.\n\nArchitecture\n------------\n- The engine (model + tokenizer + KVCacheManager) lives in one thread.\n  PyTorch is not async-safe; all model.forward() calls must happen in\n  the same OS thread to avoid CUDA context conflicts.\n- FastAPI handlers submit work via asyncio Futures and await them.\n  The worker thread resolves the futures from the executor thread using\n  loop.call_soon_threadsafe().\n- Streaming responses are handled via asyncio.Queue: the worker pushes\n  tokens as they are generated; the handler reads from the queue and\n  yields SSE events.\n\nBatching\n--------\nThe worker's dispatch() coroutine receives a Batch (from BatchQueue) and\ncalls engine.generate_batch() when the batch has >1 request, or\nengine.generate() for singletons.  Results are mapped back to per-request\nfutures.","loc":270,"bytes":11813,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[{"name":"EngineWorker","kind":"class","lineno":46,"summary":"Wraps a KVBoost InferenceEngine for async use from FastAPI.","is_public":true}],"functions":[]},{"name":"kvboost.server.schema","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/schema.py","rel_path":"src/kvboost/server/schema.py","summary":"OpenAI-compatible request / response schemas.","docstring":"OpenAI-compatible request / response schemas.\n\nImplements the subset of the OpenAI API used by most clients:\n  POST /v1/completions       \u2014 text completion\n  POST /v1/chat/completions  \u2014 chat completion (messages list)\n  GET  /v1/models            \u2014 model listing\n\nStreaming (stream=True) returns Server-Sent Events in the same format as\nthe OpenAI API so that any SSE-aware client works without changes.\n\nReferences:\n  https://platform.openai.com/docs/api-reference/completions\n  https://platform.openai.com/docs/api-reference/chat","loc":229,"bytes":9771,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[{"name":"CompletionRequest","kind":"class","lineno":37,"summary":"","is_public":true},{"name":"CompletionChoice","kind":"class","lineno":72,"summary":"","is_public":true},{"name":"UsageStats","kind":"class","lineno":79,"summary":"","is_public":true},{"name":"CompletionResponse","kind":"class","lineno":85,"summary":"","is_public":true},{"name":"CompletionChunk","kind":"class","lineno":95,"summary":"","is_public":true},{"name":"ContentPart","kind":"class","lineno":105,"summary":"","is_public":true},{"name":"FunctionCall","kind":"class","lineno":110,"summary":"","is_public":true},{"name":"ToolCall","kind":"class","lineno":115,"summary":"","is_public":true},{"name":"ChatMessage","kind":"class","lineno":121,"summary":"","is_public":true},{"name":"FunctionDef","kind":"class","lineno":140,"summary":"","is_public":true},{"name":"Tool","kind":"class","lineno":146,"summary":"","is_public":true},{"name":"ChatCompletionRequest","kind":"class","lineno":151,"summary":"","is_public":true},{"name":"ChatChoice","kind":"class","lineno":236,"summary":"","is_public":true},{"name":"ChatCompletionResponse","kind":"class","lineno":242,"summary":"","is_public":true},{"name":"ChatCompletionChunk","kind":"class","lineno":252,"summary":"","is_public":true},{"name":"ModelCard","kind":"class","lineno":262,"summary":"","is_public":true},{"name":"ModelList","kind":"class","lineno":269,"summary":"","is_public":true},{"name":"PendingRequest","kind":"class","lineno":276,"summary":"Internal wrapper carried through the batch queue.","is_public":true}],"functions":[{"name":"_request_id","kind":"function","lineno":31,"summary":"","is_public":false}]},{"name":"kvboost.server.tool_parsers","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/server/tool_parsers.py","rel_path":"src/kvboost/server/tool_parsers.py","summary":"Tool-call parsers for OpenAI-compatible function calling.","docstring":"Tool-call parsers for OpenAI-compatible function calling.\n\nModels emit tool calls in their own native syntax inside the assistant\noutput. This module converts that text into a list of ToolCall objects and\nreturns the cleaned text content (with the tool-call markup stripped).\n\nSupported parsers\n-----------------\nhermes : <tool_call>{\"name\": \"...\", \"arguments\": {...}}</tool_call>\n         Used by Qwen2.5/Qwen3, Hermes 2/3, NousResearch fine-tunes.","loc":177,"bytes":7130,"group":"server","color":"#ec4899","emoji":"\ud83d\ude80","classes":[{"name":"StreamingHermesParser","kind":"class","lineno":90,"summary":"Incremental Hermes tool-call parser for SSE streaming.","is_public":true}],"functions":[{"name":"parse_hermes","kind":"function","lineno":32,"summary":"Extract Hermes-style <tool_call>{...}</tool_call> blocks.","is_public":true},{"name":"parse","kind":"function","lineno":77,"summary":"","is_public":true},{"name":"make_streaming_parser","kind":"function","lineno":209,"summary":"","is_public":true}]},{"name":"kvboost.streaming","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/__init__.py","rel_path":"src/kvboost/streaming/__init__.py","summary":"KVBoost streaming inference backend.","docstring":"KVBoost streaming inference backend.\n\nThis package provides an AirLLM-style layer streaming runtime for running\nlarge AWQ-quantized causal LLMs with limited VRAM by:\n\n- Keeping quantized weights in pinned host RAM\n- Streaming decoder layers into GPU staging buffers\n- Reusing KVBoost's existing DynamicCache + chunk reuse pipeline\n- Using fused AWQ kernels (Marlin / ExLlamaV2)\n- Supporting partial layer residency\n\nPrimary entrypoints:\n\n- StreamingConfig\n- StreamingCausalLM","loc":23,"bytes":755,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[]},{"name":"kvboost.streaming.awq_loader","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/awq_loader.py","rel_path":"src/kvboost/streaming/awq_loader.py","summary":"# src/kvboost/streaming/awq_loader.py","docstring":"","loc":755,"bytes":27724,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"DeviceSpec","kind":"class","lineno":31,"summary":"","is_public":true},{"name":"TensorSpec","kind":"class","lineno":140,"summary":"","is_public":true},{"name":"LayerSpec","kind":"class","lineno":156,"summary":"","is_public":true},{"name":"AWQIndex","kind":"class","lineno":164,"summary":"","is_public":true},{"name":"AWQLoader","kind":"class","lineno":181,"summary":"Production-grade AWQ loader for KVBoost streaming.","is_public":true}],"functions":[{"name":"detect_device","kind":"function","lineno":42,"summary":"","is_public":true},{"name":"_resolve_dotted_attribute","kind":"function","lineno":930,"summary":"","is_public":false},{"name":"_assign_dotted_attribute","kind":"function","lineno":938,"summary":"Navigate ``root`` to the parent of the dotted path and set the leaf.","is_public":false}]},{"name":"kvboost.streaming.config","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/config.py","rel_path":"src/kvboost/streaming/config.py","summary":"# src/kvboost/streaming/config.py","docstring":"","loc":144,"bytes":4343,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"StreamingConfig","kind":"class","lineno":18,"summary":"Configuration for KVBoost streaming inference.","is_public":true}],"functions":[]},{"name":"kvboost.streaming.demo_compare_mlx","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/demo_compare_mlx.py","rel_path":"src/kvboost/streaming/demo_compare_mlx.py","summary":"Side-by-side comparison: KVBoost (MPS, pure-torch AWQ) vs mlx-lm.","docstring":"Side-by-side comparison: KVBoost (MPS, pure-torch AWQ) vs mlx-lm.\n\nRuns the same prompt through both stacks and reports load time, peak\nRSS, and decode tok/s. Not a controlled experiment \u2014 the two paths use\n*different* quantization formats and *different* runtimes. This is a\nballpark sanity check, not a benchmark.\n\nRun::\n\n    pip install mlx-lm\n    python -m kvboost.streaming.demo_compare_mlx","loc":201,"bytes":6693,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"RunResult","kind":"class","lineno":28,"summary":"","is_public":true}],"functions":[{"name":"_rss_gb","kind":"function","lineno":39,"summary":"","is_public":false},{"name":"_run_kvboost","kind":"function","lineno":47,"summary":"","is_public":false},{"name":"_run_mlx","kind":"function","lineno":107,"summary":"","is_public":false},{"name":"_print_result","kind":"function","lineno":166,"summary":"","is_public":false},{"name":"main","kind":"function","lineno":177,"summary":"","is_public":true}]},{"name":"kvboost.streaming.demo_full_resident_3b","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/demo_full_resident_3b.py","rel_path":"src/kvboost/streaming/demo_full_resident_3b.py","summary":"Parity-baseline demo: Qwen2.5-3B-AWQ in full_resident mode.","docstring":"Parity-baseline demo: Qwen2.5-3B-AWQ in full_resident mode.\n\nUsed as the throughput / correctness reference that the streaming\n``demo_partial_8b`` is compared against. Same I/O, same KV cache; only the\nresidency policy differs.\n\nRun::\n\n    python -m kvboost.streaming.demo_full_resident_3b","loc":51,"bytes":2049,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"main","kind":"function","lineno":20,"summary":"","is_public":true}]},{"name":"kvboost.streaming.demo_mps_token_by_token","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/demo_mps_token_by_token.py","rel_path":"src/kvboost/streaming/demo_mps_token_by_token.py","summary":"Token-by-token MPS demo for ``StreamingCausalLM``.","docstring":"Token-by-token MPS demo for ``StreamingCausalLM``.\n\nLoads an AWQ model on Apple Silicon (unified memory, no real streaming \u2014\nsee :mod:`kvboost.streaming.model_shell` ``_from_pretrained_mps``) and\nprints each generated token as it's produced. Two modes:\n\n- ``--mode streamer``: uses HF's :class:`TextStreamer` for a one-liner\n  streaming output. Tokens print as a continuous string.\n- ``--mode manual``: explicit greedy decode loop with per-token timing.\n  Prints token id, decoded piece, elapsed ms, running tok/s. Useful for\n  measuring exactly where time is going on the pure-torch AWQ path.\n\nRun::\n\n    python -m kvboost.streaming.demo_mps_token_by_token\n    python -m kvboost.streaming.demo_mps_token_by_token --mode manual --max-new-tokens 32","loc":218,"bytes":9245,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"_pick_device","kind":"function","lineno":29,"summary":"","is_public":false},{"name":"_format_prompt","kind":"function","lineno":38,"summary":"","is_public":false},{"name":"_run_streamer","kind":"function","lineno":50,"summary":"","is_public":false},{"name":"_run_manual","kind":"function","lineno":63,"summary":"Explicit greedy decode loop using ``DynamicCache`` for KV reuse.","is_public":false},{"name":"_load_model","kind":"function","lineno":127,"summary":"Helper for the benchmark path.","is_public":false},{"name":"_measure_decode","kind":"function","lineno":146,"summary":"Run a greedy decode and return ``(seconds, new_tokens, output_text)``.","is_public":false},{"name":"main","kind":"function","lineno":163,"summary":"","is_public":true}]},{"name":"kvboost.streaming.demo_partial_8b","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/demo_partial_8b.py","rel_path":"src/kvboost/streaming/demo_partial_8b.py","summary":"Manual VRAM-savings demo.","docstring":"Manual VRAM-savings demo.\n\nLoads an AWQ model that does NOT fit fully into the local GPU and runs\ngreedy decode using :class:`StreamingCausalLM` with partial residency.\nStreams output token-by-token, prints peak VRAM, per-token \u0394t, running\ntok/s, and the generated text.\n\nRun::\n\n    python -m kvboost.streaming.demo_partial_8b \\\n        --model casperhansen/llama-3-8b-instruct-awq \\\n        --prompt \"Explain entropy in two sentences.\"\n\nThe defaults target the 4 GB GPU class described in the plan. With\n``keep_first_k=2 keep_last_k=2`` only 4 layers stay resident; the rest\nstream from pinned host RAM. Expect ~7\u201310 tok/s on PCIe 4.0 x16 \u2014 this is\na VRAM-savings tool, not a throughput tool.","loc":211,"bytes":9013,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"_greedy_decode_streaming","kind":"function","lineno":31,"summary":"Manual greedy decode loop with per-token streaming output and timing.","is_public":false},{"name":"main","kind":"function","lineno":130,"summary":"","is_public":true}]},{"name":"kvboost.streaming.kernels","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/kernels/__init__.py","rel_path":"src/kvboost/streaming/kernels/__init__.py","summary":"AWQ kernel wrappers for streamed linear layers.","docstring":"AWQ kernel wrappers for streamed linear layers.\n\nPublic entry points:\n\n- :func:`awq_linear` \u2014 choose Marlin/ExLlamaV2/torch fallback automatically.\n- :func:`awq_dequantize_reference` \u2014 pure-torch reference for parity tests.\n\nThe wrappers accept the standard AWQ tensor layout produced by AutoAWQ:\n\n- ``qweight``: ``(in_features, out_features // pack)`` int32, packed 4-bit\n- ``scales``:  ``(in_features // group_size, out_features)`` fp16\n- ``qzeros``:  ``(in_features // group_size, out_features // pack)`` int32\n- ``bias``:    ``(out_features,)`` fp16 or None\n\n``pack`` is 8 for 4-bit AWQ. ``group_size`` is read from ``quantize_config.json``\nand passed in explicitly.","loc":167,"bytes":7441,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"_shift_table","kind":"function","lineno":34,"summary":"","is_public":false},{"name":"awq_linear","kind":"function","lineno":52,"summary":"Run an AWQ-quantized linear with the best available kernel.","is_public":true},{"name":"awq_dequantize_reference","kind":"function","lineno":92,"summary":"Dequantize AWQ ``qweight`` into a dense ``(in, out)`` matrix.","is_public":true},{"name":"_torch_awq_linear","kind":"function","lineno":129,"summary":"Fused dequant + matmul, chunked along input groups.","is_public":false}]},{"name":"kvboost.streaming.kernels.exllama_awq","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/kernels/exllama_awq.py","rel_path":"src/kvboost/streaming/kernels/exllama_awq.py","summary":"ExLlamaV2 AWQ kernel fallback.","docstring":"ExLlamaV2 AWQ kernel fallback.\n\nExLlamaV2 exposes a 4-bit GEMM that accepts shapes Marlin sometimes rejects\n(e.g. odd ``out_features`` or unusual ``group_size``). We probe for the\n``exllamav2_kernels`` extension and adapt to whichever entry point is exported.","loc":49,"bytes":1764,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"_try_resolve","kind":"function","lineno":24,"summary":"","is_public":false},{"name":"exllama_awq_available","kind":"function","lineno":40,"summary":"","is_public":true},{"name":"exllama_awq_linear","kind":"function","lineno":44,"summary":"","is_public":true}]},{"name":"kvboost.streaming.kernels.marlin","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/kernels/marlin.py","rel_path":"src/kvboost/streaming/kernels/marlin.py","summary":"Marlin int4 GEMM wrapper.","docstring":"Marlin int4 GEMM wrapper.\n\nMarlin lives in ``awq_ext`` / ``vllm._C`` / ``autoawq_kernels`` depending on\nthe install. The exact symbol name has shifted between releases, so we probe\na small set of common entry points at import time and pick whichever resolves.\n\nIf none are present, :func:`marlin_awq_available` returns ``False`` and the\nhigher-level ``awq_linear`` falls back to ExLlamaV2 or pure torch.","loc":89,"bytes":3461,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"_try_resolve","kind":"function","lineno":39,"summary":"","is_public":false},{"name":"marlin_awq_available","kind":"function","lineno":56,"summary":"Whether a Marlin-style int4 GEMM kernel is importable on this system.","is_public":true},{"name":"marlin_awq_linear","kind":"function","lineno":61,"summary":"Invoke the resolved Marlin/AWQ GEMM kernel.","is_public":true},{"name":"awq_marlin_repack","kind":"function","lineno":91,"summary":"Repack an AWQ ``qweight`` into Marlin's layout, if a repack kernel is available.","is_public":true}]},{"name":"kvboost.streaming.layer_runner","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/layer_runner.py","rel_path":"src/kvboost/streaming/layer_runner.py","summary":"from __future__ import annotations","docstring":"","loc":265,"bytes":11129,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"SupportsForward","kind":"class","lineno":38,"summary":"","is_public":true},{"name":"LayerRunnerConfig","kind":"class","lineno":43,"summary":"","is_public":true},{"name":"ResidentLayerRefs","kind":"class","lineno":55,"summary":"Resident (fully-GPU) submodules.","is_public":true},{"name":"_StreamedLayerSpec","kind":"class","lineno":68,"summary":"Stand-in placeholder; the real implementation lives in :mod:`kvboost.streaming.model_shell` where streamed layers are driven via :class:`StreamingQLinear` rebinds and forward-pre h","is_public":false},{"name":"_IdentityNorm","kind":"class","lineno":82,"summary":"","is_public":false},{"name":"StreamingDecoderLayer","kind":"class","lineno":87,"summary":"Stateless decoder layer that mirrors LlamaDecoderLayer.forward.","is_public":true}],"functions":[]},{"name":"kvboost.streaming.loader","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/loader.py","rel_path":"src/kvboost/streaming/loader.py","summary":"Convenience entry point for loading a :class:`StreamingCausalLM`.","docstring":"Convenience entry point for loading a :class:`StreamingCausalLM`.","loc":26,"bytes":849,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[{"name":"load_streaming_model","kind":"function","lineno":11,"summary":"Load a streaming-capable causal LM.","is_public":true}]},{"name":"kvboost.streaming.model_shell","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/model_shell.py","rel_path":"src/kvboost/streaming/model_shell.py","summary":"Streaming Causal Language Model.","docstring":"Streaming Causal Language Model.\n\n``StreamingCausalLM`` wraps an HF causal-LM checkpoint so its decoder layers\ncan be streamed from pinned host RAM via :class:`StreamingScheduler` while\nembeddings, the final norm, and the LM head stay permanently resident.\n\nModes:\n\n- ``residency_mode=\"full_resident\"``: weights are loaded straight to the\n  device via the standard HF AWQ loader. M1 parity baseline.\n\n- ``residency_mode in {\"partial_resident\", \"ffn_only_stream\", \"full_stream\"}``:\n  the model is instantiated with ``accelerate.init_empty_weights`` so all\n  parameters land on the ``meta`` device. The AWQLoader then materializes\n  only the resident parameters onto GPU, and the quantized linear modules\n  in *streamed* decoder layers are replaced with parameterless\n  :class:`StreamingQLinear` instances. A forward-pre-hook on each streamed\n  layer asks the scheduler to stage the next layer's weights into a CUDA\n  slot and rebinds the layer's StreamingQLinear children to that slot's\n  views. The slot pointers are constant across forwards (only the bytes\n  change), preserving Marlin's launch-config cache invariant.","loc":783,"bytes":35521,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"StreamingCausalLM","kind":"class","lineno":48,"summary":"Drop-in replacement for ``AutoModelForCausalLM.from_pretrained`` with optional layer streaming.","is_public":true}],"functions":[{"name":"_strip_quantization_config","kind":"function","lineno":473,"summary":"Return a deep-copy of ``cfg`` with ``quantization_config`` fully removed from its ``__dict__``.","is_public":false},{"name":"_mps_available","kind":"function","lineno":497,"summary":"","is_public":false},{"name":"_detect_num_layers","kind":"function","lineno":521,"summary":"Walk a HF ``PretrainedConfig`` looking for the decoder layer count.","is_public":false},{"name":"_iter_decoder_layers","kind":"function","lineno":581,"summary":"","is_public":false},{"name":"_is_quant_linear","kind":"function","lineno":600,"summary":"Duck-type check for autoawq's ``WQLinear_GEMM`` / transformers' ``AwqLinear`` / similar.","is_public":false},{"name":"_iter_quant_linears","kind":"function","lineno":611,"summary":"Return ``(dotted_path_within_layer, module)`` for each quant linear inside a single decoder layer.","is_public":false},{"name":"_set_submodule","kind":"function","lineno":625,"summary":"","is_public":false},{"name":"_detect_in_out","kind":"function","lineno":633,"summary":"Read ``(in_features, out_features)`` from a quant-linear module.","is_public":false},{"name":"_replace_streamed_linears","kind":"function","lineno":645,"summary":"Replace each streamed layer's quant linears with StreamingQLinear.","is_public":false},{"name":"_replace_linears_for_quant_paths","kind":"function","lineno":676,"summary":"Replace every decoder-layer projection whose AWQ quant tensors exist in the loader's index with a :class:`StreamingQLinear`.","is_public":false},{"name":"_materialize_meta_buffers","kind":"function","lineno":750,"summary":"After resident materialization, any parameter still on the ``meta`` device that belongs to a non-streamed submodule needs *something* finite.","is_public":false},{"name":"_build_scheduler","kind":"function","lineno":775,"summary":"","is_public":false},{"name":"_strip_layer_prefix","kind":"function","lineno":862,"summary":"``model.layers.{i}.self_attn.q_proj.qweight`` \u2192 ``self_attn.q_proj.qweight``.","is_public":false},{"name":"_make_pre_hook","kind":"function","lineno":873,"summary":"Pre-hook: stage this layer's weights and rebind StreamingQLinears.","is_public":false},{"name":"_make_post_hook","kind":"function","lineno":906,"summary":"","is_public":false}]},{"name":"kvboost.streaming.pinned_pool","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/pinned_pool.py","rel_path":"src/kvboost/streaming/pinned_pool.py","summary":"Pinned host memory pool for streaming weights.","docstring":"Pinned host memory pool for streaming weights.\n\nThis is a thin handle-keyed wrapper over ``torch.empty(..., pin_memory=True)``\nplus an optional LRU eviction policy. We deliberately do NOT call\n``cudaHostAlloc`` directly: PyTorch's allocator already uses it for pinned\ntensors, and going through torch keeps the tensors usable with the standard\n``non_blocking=True`` ``copy_`` path the staging arena relies on.\n\nThe pool exists for two reasons:\n1. Give callers an opaque integer \"handle\" to a tensor so dictionaries and\n   the Rust scheduler can refer to weights without holding tensor refs.\n2. Optionally cap pinned memory and evict least-recently-used buffers when a\n   model exceeds the pinned-RAM budget (LRU pin/unpin from the plan).\n\nPinned memory is a system-wide resource (``ulimit -l``); evicting just means\ndropping the tensor and re-staging it on next access from the safetensors\nshard. Eviction is opt-in.","loc":155,"bytes":7455,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"PinnedMemoryPool","kind":"class","lineno":33,"summary":"Handle-indexed pool of pinned host tensors with optional LRU eviction.","is_public":true}],"functions":[]},{"name":"kvboost.streaming.qkv_proj","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/qkv_proj.py","rel_path":"src/kvboost/streaming/qkv_proj.py","summary":"Streaming AWQ linear layer.","docstring":"Streaming AWQ linear layer.\n\n``StreamingQLinear`` is a parameterless ``nn.Module`` that holds *references*\nto slot-relative views (``qweight``, ``scales``, ``qzeros``, ``bias``) and\ndispatches to whichever AWQ GEMM kernel is available. The slot base pointer is\nstable across forwards (only the bytes inside the slot change), which keeps\nthe Marlin launch-config cache valid \u2014 see the plan's M2 risk note.\n\nFor resident layers the same module is used: ``rebind`` is called once at load\ntime with already-on-GPU tensors and never again.\n\nTwo binding modes:\n\n- **Streaming (default)**: ``rebind`` just stores references to the four\n  AWQ tensors; ``forward`` runs the AWQ kernel against them every call.\n  Required when the underlying bytes change between forwards (CUDA slot\n  recycling).\n- **Cached dense** (``cache_dense=True``): ``rebind`` dequantizes once\n  into a dense fp16 weight; ``forward`` is a plain matmul. Used by the\n  MPS / unified-memory path where weights are permanent and there's no\n  benefit to keeping them packed. Costs ~4\u00d7 memory per layer vs packed\n  but eliminates per-forward dequant.","loc":130,"bytes":6107,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"StreamingQLinear","kind":"class","lineno":35,"summary":"AWQ linear backed by tensor views (slot-relative or resident).","is_public":true}],"functions":[]},{"name":"kvboost.streaming.scheduler","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/scheduler.py","rel_path":"src/kvboost/streaming/scheduler.py","summary":"from __future__ import annotations","docstring":"","loc":233,"bytes":10069,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"StreamingLayerPlan","kind":"class","lineno":29,"summary":"","is_public":true},{"name":"StreamingScheduler","kind":"class","lineno":35,"summary":"CUDA stream scheduler for layer-by-layer weight streaming.","is_public":true}],"functions":[]},{"name":"kvboost.streaming.staging","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/staging.py","rel_path":"src/kvboost/streaming/staging.py","summary":"from __future__ import annotations","docstring":"","loc":204,"bytes":7936,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[{"name":"TensorPlacement","kind":"class","lineno":19,"summary":"A tensor's location inside one contiguous uint8 staging slot.","is_public":true},{"name":"SlotLayout","kind":"class","lineno":40,"summary":"Static layout for one streamed layer slot.","is_public":true},{"name":"StagingSlot","kind":"class","lineno":122,"summary":"Raw CUDA byte buffer for one streamed layer.","is_public":true},{"name":"StagingArena","kind":"class","lineno":198,"summary":"Two-slot CUDA staging arena for ping-pong layer streaming.","is_public":true}],"functions":[{"name":"align_up","kind":"function","lineno":12,"summary":"","is_public":true}]},{"name":"kvboost.streaming.streaming_sched","path":"/Users/srihariunnikrishnan/Documents/kv_cache/src/kvboost/streaming/streaming_sched.py","rel_path":"src/kvboost/streaming/streaming_sched.py","summary":"Python-side proxy for the Rust ``StreamingSchedulerBackend``.","docstring":"Python-side proxy for the Rust ``StreamingSchedulerBackend``.\n\nThe actual implementation lives in [crates/kvboost_native/src/streaming_sched.rs](../../../crates/kvboost_native/src/streaming_sched.rs)\nand is exposed through the ``kvboost_native`` PyO3 module. This file just\nre-exports the class so callers can do::\n\n    from kvboost.streaming.streaming_sched import StreamingSchedulerBackend\n\nwithout having to know about the native module layout. If the Rust extension\nhasn't been built (``maturin develop`` in ``crates/kvboost_native``), the\nimport below raises :class:`ImportError` with a hint.","loc":21,"bytes":1080,"group":"streaming","color":"#a855f7","emoji":"\ud83c\udf0a","classes":[],"functions":[]}],"extras":[{"rel_path":"src/kvboost/csrc/flash_attn_kernel.cu","loc":255,"bytes":11488,"lang":"cu"},{"rel_path":"src/kvboost/csrc/flash_attn.cpp","loc":85,"bytes":4007,"lang":"cpp"},{"rel_path":"src/kvboost/csrc/flash_attn.h","loc":11,"bytes":321,"lang":"h"},{"rel_path":"crates/kvboost_native/src/block_allocator.rs","loc":145,"bytes":5412,"lang":"rs"},{"rel_path":"crates/kvboost_native/src/lib.rs","loc":16,"bytes":611,"lang":"rs"},{"rel_path":"crates/kvboost_native/src/streaming_sched.rs","loc":175,"bytes":7295,"lang":"rs"}],"stats":{"module_count":43,"extra_file_count":6,"total_loc":9921,"feature_count":6}};
